121	function installFetchMock() {
122	  fetchMock.mockImplementation(async (input: RequestInfo | URL, init?: RequestInit) => {
123	    const url = String(input);
124	    const method = init?.method ?? "GET";
125	
126	    if (method === "GET" && url === "/api/property/tenants") return jsonResponse(TENANTS);
127	    if (method === "GET" && url === "/api/property/invoices") return jsonResponse(INVOICES);
128	    if (method === "GET" && url === "/api/property/schedules") return jsonResponse(schedules);
129	    if (method === "GET" && url === "/api/property/reminder-settings") {
130	      return jsonResponse(reminderSettings);
131	    }
132	    if (method === "PUT" && url === "/api/property/reminder-settings") {
133	      const patch = JSON.parse(String(init?.body ?? "{}"));
134	      reminderPuts.push(patch);
135	      /* Persist, as the server does — the component writes the response back
136	         into the cache, so a non-persisting mock would mask a working save. */
137	      reminderSettings = { ...reminderSettings, ...patch };
138	      return jsonResponse(reminderSettings);
139	    }
140	    const scheduleRoute = url.match(/^\/api\/property\/schedules\/([\w-]+)$/);
141	    if (scheduleRoute && (method === "PUT" || method === "DELETE")) {
142	      const body = method === "PUT" ? JSON.parse(String(init?.body ?? "{}")) : {};
143	      scheduleCalls.push(
144	        method === "PUT"
145	          ? `status:${scheduleRoute[1]}:${body.status}`
146	          : `delete:${scheduleRoute[1]}`,
147	      );
148	      return jsonResponse({ id: scheduleRoute[1] });
149	    }
150	    if (method === "POST" && url === "/api/property/invoices") {
151	      const body = JSON.parse(String(init?.body ?? "{}"));
152	      invoicePosts.push(body);
153	      return jsonResponse({ id: `new-${invoicePosts.length}` });
154	    }
155	    if (method === "POST" && url === "/api/property/invoices/document") {
156	      const body = init?.body as FormData;
157	      const file = body.get("document") as File;
158	      docUploads.push(file.name);
159	      return docUploadHandler(file);
160	    }
161	    const rowAction = url.match(
162	      /^\/api\/property\/invoices\/([\w-]+)\/(resend|void|mark-paid-external)$/,
163	    );
164	    if (method === "POST" && rowAction) {
165	      rowActionCalls.push(`${rowAction[2]}:${rowAction[1]}`);
166	      if (rowAction[2] === "mark-paid-external") {
167	        markPaidBodies.push(JSON.parse(String(init?.body ?? "{}")));
168	      }
169	      return jsonResponse({ id: rowAction[1] });
170	    }
171	    throw new Error(`Unhandled test request: ${method} ${url}`);
172	  });
173	}
174	
175	function renderTerminal() {
176	  const queryClient = new QueryClient({
177	    defaultOptions: {
178	      queries: { retry: false, staleTime: 0 },
179	      mutations: { retry: false },
180	    },
181	  });
182	  const user = userEvent.setup();
183	  const rendered = render(
