await page.locator(".pt-tenant-cards").getByRole("button", { name: /Mia Chen/ }).click();
await shot("3-request-seeded");

/* recurring frequency */
await page.getByRole("button", { name: "weekly", exact: true }).click();
await shot("4-request-weekly");

/* keypad */
