diff --git a/scripts/verify-terminal-dock.mjs b/scripts/verify-terminal-dock.mjs
index 7cfcaa7..79b44f2 100644
--- a/scripts/verify-terminal-dock.mjs
+++ b/scripts/verify-terminal-dock.mjs
@@ -132,8 +132,42 @@ async function checkDockContract(page, label) {
     );
   }

-  /* Collapsed: wait out the idle timer and re-read. */
-  await page.waitForTimeout(COLLAPSE_AFTER_MS + 900);
+  /* Clause 8's second half: "updates within one frame of a state change". The
+     wrapper's height is transitioned over 0.5s, so the honest test is not that
+     the token jumps but that it *tracks* — sampled mid-collapse it must equal
+     the live box and sit strictly between the two resting heights. A token
+     written once at transitionend passes the resting assertions below and fails
+     this one. */
+  await page.waitForTimeout(COLLAPSE_AFTER_MS - 250);
+  const mid = await page.evaluate(async () => {
+    /* Sample a few frames into the transition. */
+    await new Promise((resolve) => setTimeout(resolve, 400));
+    const nav = document.querySelector('nav[data-demo-id="terminal-dock"]');
+    const raw = getComputedStyle(document.documentElement)
+      .getPropertyValue("--dock-h")
+      .trim();
+    return {
+      px: raw ? Number.parseFloat(raw) : null,
+      rect: nav ? nav.getBoundingClientRect().height : null,
+    };
+  });
+  if (mid.px === null || mid.rect === null) {
+    fail(`${label}: could not sample --dock-h mid-collapse (§4.3 clause 8)`);
+  } else {
+    if (Math.abs(mid.px - mid.rect) > 1.5) {
+      fail(
+        `${label}: mid-collapse --dock-h was ${mid.px}px while the dock measured ${mid.rect}px — the token lags the box instead of tracking it (§4.3 clause 8)`,
+      );
+    }
+    if (mid.rect > DOCK_COLLAPSED + 1 && mid.rect < DOCK_EXPANDED - 1 && mid.px === DOCK_EXPANDED) {
+      fail(
+        `${label}: --dock-h stayed at ${DOCK_EXPANDED}px through a collapse in progress (§4.3 clause 8)`,
+      );
+    }
+  }
+
+  /* Collapsed: wait out the rest of the idle timer and re-read. */
+  await page.waitForTimeout(1_200);
   const collapsed = await readDockH(page);
   const collapsedRect = await navRect(page);

@@ -153,6 +187,7 @@ async function checkDockContract(page, label) {
   return {
     expanded: expanded.raw || "(unset)",
     expandedRect: rect ? Math.round(rect.height) : null,
+    midCollapse: mid.px === null ? null : `${Math.round(mid.px)}px vs box ${Math.round(mid.rect)}px`,
     collapsed: collapsed.raw || "(unset)",
     collapsedRect: collapsedRect ? Math.round(collapsedRect.height) : null,
   };
